"""Generate an accessible, buildless course website from the shared course data."""
import html
import json
import math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
C=json.loads((ROOT/'course.json').read_text());P=json.loads((ROOT/'course_papers.json').read_text());R=json.loads((ROOT/'projects.json').read_text())
P = sorted(P, key=lambda p: (C['reading_categories'].index(p['category']), p['year'], p['id']))
def e(v):return html.escape(str(v),quote=True)
def paras(items):return ''.join('<p>'+e(x)+'</p>' for x in items)
def lis(items):return '<ul>'+''.join('<li>'+e(x)+'</li>' for x in items)+'</ul>'
def collection(p): return 'Mudassir Shabbir · research' if p.get('instructor_paper') else ('Recent research' if p.get('recent_addition') else 'Field landmark')
def graph():
    nodes=[(280+math.cos(i*math.pi*2/12)*r,235+math.sin(i*math.pi*2/12)*r*.82) for i,r in enumerate([190,155,210,165,200,180,210,160,190,180,205,175])]+[(220,180),(320,170),(350,280),(230,300),(280,245)]
    edges=[(i,(i+1)%12) for i in range(12)]+[(i,(i+3)%12) for i in [0,2,5,7,9]]+[(i,12+i%4) for i in range(12)]+[(12,13),(13,14),(14,15),(15,12)]+[(16,i) for i in range(12,16)]
    s='<svg viewBox="0 0 560 490" role="img" aria-labelledby="graph-title"><title id="graph-title">Connected nodes illustrate how information travels through a graph</title><g class="graph-edges">'
    s+=''.join(f'<line x1="{nodes[a][0]:.2f}" y1="{nodes[a][1]:.2f}" x2="{nodes[b][0]:.2f}" y2="{nodes[b][1]:.2f}"/>' for a,b in edges)+'</g><g class="graph-nodes">'
    s+=''.join(f'<circle cx="{x:.2f}" cy="{y:.2f}" r="{7 if i!=16 else 14}" class="{("center" if i==16 else "")}"/>' for i,(x,y) in enumerate(nodes))
    return s+'</g><text x="275" y="250" class="node-label">h</text><text x="38" y="460" class="figure-label">NODES + EDGES → REPRESENTATIONS</text></svg>'

weeks=''.join(f'''<details class="week"><summary><span class="mono week-number">{w['week']:02}</span><span>{e(w['topic'])}</span><span class="week-papers">{len(w['papers']) if w['papers'] else '—'} {'paper' if len(w['papers'])==1 else 'papers'}</span><span class="toggle" aria-hidden="true">+</span></summary><div class="week-content"><p>{e(w['detail'])}</p><p class="activity">{e(w['activity'])}</p><p class="paper-refs">{''.join(f'<a href="#{pid}" class="paper-ref">{pid}</a>' for pid in w['papers']) or e(w['reading'])}</p></div></details>''' for w in C['weeks'])
papers=''.join(f'''<article class="paper" id="{p['id']}" data-year="{p['year']}" data-category="{e(p['category'])}" data-search="{e(' '.join(str(p[k]) for k in ['id','title','authors','year','category','method']).lower())}"><div class="paper-number mono">{p['id']}<span>{p['year']}</span></div><div><div class="paper-meta">{e(collection(p))} · {e(p['category'])} <span> / {e(p['difficulty'])}</span></div><h3><a href="{e(p['url'])}" target="_blank" rel="noopener noreferrer">{e(p['title'])} <span class="external" aria-label="opens primary source">↗</span></a></h3><p class="byline">{e(p['authors'])} · {e(p['venue'])}</p><p>{e(p['why'])}</p>{('<p class="fine-print">'+e(p['display_note'])+'</p>') if p.get('display_note') else ''}<details class="exercise"><summary>Reproduction idea <span aria-hidden="true">+</span></summary><p>{e(p['exercise'])}</p></details></div></article>''' for p in P)
projects=''.join(f'''<details class="project"><summary><span class="mono">{r['id']}</span><span>{e(r['title'])}</span><span class="toggle" aria-hidden="true">+</span></summary><div class="project-content"><p class="question">{e(r['question'])}</p><dl>{''.join(f'<dt>{label}</dt><dd>{e(r[key])}</dd>' for key,label in [('data','Data'),('baselines','Baselines'),('evaluation','Evaluation'),('extension','Possible extension'),('compute','Compute estimate')])}</dl><a class="text-link" href="{e(r['source'])}" target="_blank" rel="noopener noreferrer">Dataset documentation ↗</a></div></details>''' for r in R)
assess=''.join(f'<li><div><h3>{e(a["name"])}</h3><p>{e(a["detail"])}</p></div><span class="weight">{a["weight"]}<small>%</small></span></li>' for a in C['assessment'])
phases=''.join(f'<li><span class="mono">WEEK {ph["week"]}</span><h3>{e(ph["name"])} <small>{ph["weight"]}%</small></h3><p>{e(ph["deliverable"])}</p></li>' for ph in C['phases'])
categories=''.join(f'<option>{e(cat)}</option>' for cat in dict.fromkeys(p['category'] for p in P))
resources=''.join(f'<li><a href="{e(r["url"])}" target="_blank" rel="noopener noreferrer">{e(r["title"])} ↗</a><span>{e(r["author"])} · {e(r["use"])}</span></li>' for r in C['resources'])
page=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f6f5f0"><meta name="description" content="CS4308 Graph Machine Learning: a research and practice course with 50 curated papers, five-paper reproductions, and a phased research project."><title>CS4308 · Graph Machine Learning</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/course.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a>
<header class="site-header"><a class="wordmark" href="#" aria-label="CS4308 home">CS<span>4308</span><i aria-hidden="true"></i></a><nav aria-label="Main navigation"><a href="#course">The course</a><a href="#schedule">Schedule</a><a href="#papers">50 papers</a><a href="#projects">Projects</a><a href="#downloads" class="nav-download">Downloads <span aria-hidden="true">↗</span></a></nav></header>
<main id="main">
<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> RESEARCH + PRACTICE · CS4308</p><h1>Graph<br>Machine<br><em>Learning.</em></h1><p class="hero-deck">The world is connected.<br>Learn to build models that see the connections.</p><div class="hero-actions"><a class="button" href="#course">Explore the course <span aria-hidden="true">↓</span></a><a class="text-link" href="CS4308_Course_Outline.pdf">Read the syllabus ↗</a></div></div><div class="hero-visual">{graph()}<div class="graph-caption"><span class="mono">FIG. 01</span><p>From relationships<br>to representations.</p></div></div></section>
<div class="course-strip"><div><strong>50</strong><span>papers to explore</span></div><div><strong>5</strong><span>paper studies per group</span></div><div><strong>2</strong><span>students per group, normally</span></div><div><strong>1</strong><span>research paper per student</span></div></div>
<section id="course" class="section split"><div><p class="eyebrow">01 / THE COURSE</p><h2>Read the paper.<br>Build the model.<br><em>Ask the next question.</em></h2></div><div class="prose"><p class="lead">{e(C['description'])}</p><p>You will move between mathematical ideas, working code, and research discussions. Follow a method from its assumptions to its results—and learn to test the claims yourself.</p><p>Bring curiosity about networks, molecules, recommendations, or scientific discovery. Leave with a reproduction portfolio, a research artifact, and a paper you can defend.</p><div class="course-facts"><div><span>FORMAT</span><p>Lectures, paper discussions & practical studios</p></div><div><span>DURATION</span><p>16 weeks proposed, including exams</p></div><div><span>PREPARATION</span><p>Python, linear algebra, probability & introductory ML</p></div><div><span>OFFERING</span><p>Semester & instructor to be announced</p></div></div><p class="status-note">{e(C['status'])}</p></div></section>
<section class="section outcomes"><div class="section-heading"><p class="eyebrow">WHAT YOU WILL LEARN</p><h2>From graph structure<br>to research judgment.</h2></div><ol class="outcome-list">{''.join(f'<li><span class="mono">0{i+1}</span><p>{e(x)}</p></li>' for i,x in enumerate(C['outcomes']))}</ol><details class="more"><summary>Preparation, workload & course logistics <span aria-hidden="true">+</span></summary><div class="prose">{lis(C['prerequisites'])}<p>{e(C['meetings'])}</p><p>{e(C['credits'])}. {e(C['workload'])}</p><p>Proposed as an elective for senior undergraduates and graduate students with permission. Formal eligibility, prerequisites, room, office hours, TA support, and contact details will be announced.</p></div></details></section>
<section id="schedule" class="section"><div class="section-heading horizontal"><div><p class="eyebrow">02 / THE SEMESTER</p><h2>A path through<br><em>connected ideas.</em></h2></div><p>Graph theory first. Research and implementation throughout. Expand a week to see its readings and practical work.</p></div><div class="schedule-head mono"><span>WEEK</span><span>TOPIC</span><span>READINGS</span></div><div class="schedule">{weeks}</div><p class="fine-print">Proposed sequence. Checkpoints and exam weeks may move to match the official academic calendar. All 50 papers receive class coverage through lectures, spotlights, and group discussions.</p></section>
<section id="papers" class="section readings"><div class="section-heading horizontal"><div><p class="eyebrow">03 / THE READING ROOM</p><h2>50 papers.<br><em>A field in perspective.</em></h2></div><p>{e(C['reading_selection']['summary'])}</p></div><div class="reading-guide"><p><strong>Read broadly. Reproduce deeply.</strong> The class explores all 50 papers. Each pair understands, implements, evaluates, and presents at least five. For theory or benchmark papers, implement the central diagnostic or evaluation protocol.</p><a class="text-link" href="CS4308_Papers.pdf">Get the reading companion ↗</a></div><details class="more"><summary>How the 50 papers were selected <span aria-hidden="true">+</span></summary><div class="prose">{paras(C["reading_selection"]["policy"])}<p>Coverage checked against <a href="https://orcid.org/0000-0002-6961-0961">the author’s ORCID record</a>, <a href="https://anwar-said.github.io/anwarsaid/CV.pdf">a coauthor’s publication list</a>, and linked publisher or manuscript records. <a href="reading_selection.json">View the coverage and version notes ↗</a></p></div></details><div class="paper-controls"><label><span>Search papers</span><input id="paper-search" type="search" placeholder="Try GAT, foundation models…" autocomplete="off"></label><label><span>Topic</span><select id="paper-category"><option value="">All topics</option>{categories}</select></label><label><span>Publication year</span><select id="paper-year"><option value="">All years</option>{"".join(f"<option>{year}</option>" for year in sorted(set(p["year"] for p in P),reverse=True))}</select></label><button id="reset-papers" type="button">Reset</button></div><button id="author-papers" class="author-filter" type="button">Explore Mudassir Shabbir’s {sum(p.get("instructor_paper",False) for p in P)} papers ↗</button><p id="paper-count" class="mono result-count" role="status" aria-live="polite">50 of 50 papers</p><div class="paper-list">{papers}</div><p id="no-results" hidden>No papers match that search. Try another term or reset the filters.</p><p class="fine-print">Publication years follow the cited venue; preprint dates may differ. Workshop publications are labeled. Bibliographic sources checked in November 2026. GAN refers to adversarial generation; GAT refers to graph attention.</p></section>
<section id="practice" class="section split"><div><p class="eyebrow">04 / HOW WE WORK</p><h2>Research is<br><em>a practice.</em></h2><p class="side-note">A strong result can be a new method, an informative failure, or a careful replication that changes what we understand.</p></div><div><h3 class="subhead">The five-paper portfolio</h3><div class="prose">{paras(C['paper_protocol'][1:])}</div><details class="more"><summary>What counts as a reproducible study? <span aria-hidden="true">+</span></summary><div class="prose">{paras(C['policies'][2:5])}</div></details></div></section>
<section id="assessment" class="section"><div class="section-heading horizontal"><div><p class="eyebrow">05 / ASSESSMENT</p><h2>Ideas, evidence,<br><em>and individual understanding.</em></h2></div><p>A proposed balance of practical research and individual assessment. The weights below total 100% and will be confirmed before the course begins.</p></div><ul class="assessment-list">{assess}</ul><p class="fine-print">No separate graded homework or attendance component is proposed. Exam dates, permitted aids, late-work rules, and quiz make-up arrangements will be announced under university policy. Shared work is accompanied by individual contribution statements and oral checks.</p></section>
<section id="projects" class="section"><div class="section-heading horizontal"><div><p class="eyebrow">06 / THE RESEARCH PROJECT</p><h2>Choose a question.<br><em>Make it your own.</em></h2></div><p>Build a project in phases, from a testable hypothesis to reproducible evidence. Each student writes and submits an individual research paper on the work.</p></div><ol class="phase-list">{phases}</ol><div class="research-note prose"><p>{e(C['research_standard'])}</p><p><strong>Paper structure.</strong> {e(C['paper_structure'])}</p><p>{e(C['project_rubric'])}</p></div><div class="project-intro"><h3>20 places to begin</h3><p>Illustrative questions, not a fixed menu. Expand an idea for data, baselines, evaluation, and a possible extension. Compute estimates are approximate; scope each project with the instructor.</p></div><div class="project-list">{projects}</div></section>
<section id="downloads" class="section downloads"><div><p class="eyebrow">07 / TAKE A CLOSER LOOK</p><h2>Your next research<br>question could<br><em>start here.</em></h2><p>Explore the syllabus and shortlist a few papers. Enrollment details and the official offering will be announced through university registration channels.</p></div><div class="download-list"><a href="CS4308_Course_Outline.pdf"><span>Course outline<small>Completed form + project ideas · PDF</small></span><b aria-hidden="true">↓</b></a><a href="CS4308_Course_Outline.docx"><span>Editable course outline<small>Word document · DOCX</small></span><b aria-hidden="true">↓</b></a><a href="CS4308_Papers.pdf"><span>Reading companion<small>50 papers + 20 project briefs · PDF</small></span><b aria-hidden="true">↓</b></a><a href="CS4308_Papers.tex"><span>Reading companion source<small>Editable LaTeX · TEX</small></span><b aria-hidden="true">↓</b></a></div></section>
<section class="section resources"><div><p class="eyebrow">SUPPORTING RESOURCES</p><h2>Keep exploring.</h2></div><ul>{resources}</ul></section>
<section class="policy-note"><details><summary>Course status, support & academic practice <span aria-hidden="true">+</span></summary><div class="prose">{paras([C['status'],C['policies'][0],C['policies'][1],C['policies'][-1]])}<p>For student support and accessibility resources, consult <a href="https://advising.lums.edu.pk/#supportservices" target="_blank" rel="noopener noreferrer">LUMS student support services ↗</a>. The downloadable form retains the university policy text supplied in the original template.</p></div></details></section>
</main><footer><a class="wordmark" href="#">CS<span>4308</span><i aria-hidden="true"></i></a><p>Graph Machine Learning<br><span>A research and practice course</span></p><a href="https://github.com/amessbee/s27">Course repository ↗</a></footer></body></html>'''
(ROOT/'index.html').write_text(page)
